","/**
 * DarkOps Customer Assistant — Conversation Engine
 * Multi-step conversation state machine for customer support flows.
 */

export type FlowType = "complaint" | "track" | "refund" | "contact" | null;

export type ComplaintStep =
 | "category"
 | "order_number"
 | "description"
 | "photo"
 | "confirmation";

export type TrackStep = "ask_id" | "show_timeline";
export type RefundStep = "ask_id" | "show_status";

export interface ConversationState {
 activeFlow: FlowType;
 complaintStep: ComplaintStep;
 trackStep: TrackStep;
 refundStep: RefundStep;
 collectedData: {
 category?: string;
 orderNumber?: string;
 description?: string;
 wantsPhoto?: boolean;
 complaintId?: string;
 refundId?: string;
 };
}

export interface SectionItem {
 title: string;
 severity?: "critical" | "warning" | "healthy" | "info";
 badge?: string;
 bullets?: string[];
 metrics?: { label: string; value: string }[];
}

export interface EngineResponse {
 text: string;
 sections?: SectionItem[];
 chips?: string[];
 actionCards?: { icon: string; title: string; description: string; action: string }[];
 isComplete?: boolean;
}

export function getInitialState(): ConversationState {
 return {
 activeFlow: null,
 complaintStep: "category",
 trackStep: "ask_id",
 refundStep: "ask_id",
 collectedData: {},
 };
}

function now(): string {
 return new Date().toLocaleTimeString("en-US", {
 hour: "2-digit",
 minute: "2-digit",
 });
}

export function getWelcomeResponse(): EngineResponse {
 return {
 text: "Hello! I'm your DarkOps Customer Assistant. How can I help you today?",
 actionCards: [
 {
 icon: "🛡️",
 title: "Raise Complaint",
 description: "Report an issue with your order",
 action: "complaint",
 },
 {
 icon: "📋",
 title: "Track Complaint",
 description: "Check the status of an existing complaint",
 action: "track",
 },
 {
 icon: "💰",
 title: "Refund Status",
 description: "Track your refund progress",
 action: "refund",
 },
 {
 icon: "📞",
 title: "Contact Support",
 description: "Get help from our team",
 action: "contact",
 },
 ],
 };
}

export function processInput(
 input: string,
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 const lower = input.toLowerCase().trim();

 // Global reset
 if (lower === "start over" || lower === "reset" || lower === "new conversation") {
 return {
 response: getWelcomeResponse(),
 newState: getInitialState(),
 };
 }

 // If no flow active, detect intent
 if (!state.activeFlow) {
 return detectIntent(lower, state);
 }

 // Route to active flow
 switch (state.activeFlow) {
 case "complaint":
 return processComplaint(input, state);
 case "track":
 return processTrack(input, state);
 case "refund":
 return processRefund(input, state);
 case "contact":
 return processContact(input, state);
 default:
 return {
 response: getWelcomeResponse(),
 newState: getInitialState(),
 };
 }
}

function detectIntent(
 input: string,
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 // IMPORTANT: Track/refund/contact checks MUST come before complaint check
 // because "Track Complaint" contains the word "complaint"
 if (input.includes("track") || input.includes("status of complaint") || input.includes("check complaint")) {
 return startTrackFlow(state);
 }
 if (input.includes("refund") || input.includes("money back") || input.includes("payment")) {
 return startRefundFlow(state);
 }
 if (input.includes("contact") || input.includes("support") || input.includes("help") || input.includes("talk")) {
 return startContactFlow(state);
 }
 if (
 input.includes("complaint") ||
 input.includes("raise") ||
 input.includes("report") ||
 input.includes("issue") ||
 input.includes("problem")
 ) {
 return startComplaintFlow(state);
 }
 if (input.includes("refund") || input.includes("money back") || input.includes("payment")) {
 return startRefundFlow(state);
 }
 if (input.includes("contact") || input.includes("support") || input.includes("help") || input.includes("talk")) {
 return startContactFlow(state);
 }

 // Fallback
 return {
 response: {
 text: "I'm not sure what you need. Please select one of the options below, or type what you're looking for.",
 actionCards: getWelcomeResponse().actionCards,
 },
 newState: state,
 };
}

// ===== COMPLAINT FLOW =====

function startComplaintFlow(
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 return {
 response: {
 text: "I'm sorry to hear you're facing an issue. What category best describes your problem?",
 chips: [
 "Missing Item",
 "Damaged Item",
 "Wrong Product",
 "Delivery Delay",
 "Payment Issue",
 "Other",
 ],
 },
 newState: {
 ...state,
 activeFlow: "complaint",
 complaintStep: "category",
 collectedData: {},
 },
 };
}

function processComplaint(
 input: string,
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 switch (state.complaintStep) {
 case "category": {
 const categories = [
 "Missing Item",
 "Damaged Item",
 "Wrong Product",
 "Delivery Delay",
 "Payment Issue",
 "Other",
 ];
 const matched = categories.find(
 (c) => c.toLowerCase() === input.toLowerCase().trim()
 ) || input.trim();

 return {
 response: {
 text: `Got it — **${matched}**. Please provide your order number (e.g., ORD-284719).`,
 },
 newState: {
 ...state,
 complaintStep: "order_number",
 collectedData: { ...state.collectedData, category: matched },
 },
 };
 }
 case "order_number": {
 const orderNum = input.trim().toUpperCase();
 return {
 response: {
 text: `Order **${orderNum}** located. Please describe the issue briefly — what happened?`,
 },
 newState: {
 ...state,
 complaintStep: "description",
 collectedData: { ...state.collectedData, orderNumber: orderNum },
 },
 };
 }
 case "description": {
 return {
 response: {
 text: "Thank you for the details. Would you like to attach a photo as evidence?",
 chips: ["Yes, attach photo", "No, skip this"],
 },
 newState: {
 ...state,
 complaintStep: "photo",
 collectedData: { ...state.collectedData, description: input.trim() },
 },
 };
 }
 case "photo": {
 const wantsPhoto = input.toLowerCase().includes("yes");
 const data = { ...state.collectedData, wantsPhoto };
 const complaintId = `CMP-${Math.floor(10000 + Math.random() * 90000)}`;

 return {
 response: {
 text: wantsPhoto
 ? "📸 Photo upload noted (feature available in production release). Your complaint has been filed!"
 : "Your complaint has been filed successfully!",
 sections: [
 {
 title: "Complaint Confirmation",
 severity: "healthy",
 badge: complaintId,
 bullets: [
 `Category: ${data.category}`,
 `Order: ${data.orderNumber}`,
 `Description: ${data.description}`,
 `Photo: ${wantsPhoto ? "Requested (V2 feature)" : "Not attached"}`,
 `Filed at: ${now()}`,
 `Expected response: Within 2 hours`,
 ],
 },
 {
 title: "⚠️ V1 Prototype Notice",
 severity: "info",
 bullets: [
 "This is a demonstration prototype for the DarkOps hackathon.",
 "In production, this would create a real complaint ticket in ServiceNow.",
 "Notifications, SLA tracking, and escalation would be automated.",
 ],
 },
 ],
 isComplete: true,
 },
 newState: {
 ...getInitialState(),
 collectedData: data,
 },
 };
 }
 default:
 return { response: getWelcomeResponse(), newState: getInitialState() };
 }
}

// ===== TRACK COMPLAINT FLOW =====

interface TrackComplaintData {
 status: string;
 statusIcon: string;
 category: string;
 created: string;
 assignedTeam: string;
 latestUpdate: string;
 estimatedResolution: string;
 timeline: string[];
}

const TRACKED_COMPLAINTS: Record<string, TrackComplaintData> = {
 "CMP-10482": {
 status: "Under Investigation",
 statusIcon: "🟡",
 category: "Missing Item",
 created: "Today, 10:42 AM",
 assignedTeam: "Operations Team — Bangalore",
 latestUpdate:
 "Our team has verified your complaint and is coordinating with the assigned dark store.",
 estimatedResolution: "Within the next 2 hours",
 timeline: [
 "✅ Complaint Received — Today, 10:42 AM",
 "✅ AI Categorized — Today, 10:42 AM",
 "✅ Assigned to Operations — Today, 10:45 AM",
 "🟡 Investigation in Progress",
 "○ Resolution Pending",
 ],
 },
 "CMP-10291": {
 status: "Resolved",
 statusIcon: "🟢",
 category: "Delivery Delay",
 created: "Yesterday, 6:18 PM",
 assignedTeam: "Delivery Operations — HSR Layout",
 latestUpdate:
 "Your complaint has been resolved. A ₹150 credit has been applied to your account as compensation for the delay.",
 estimatedResolution: "Completed",
 timeline: [
 "✅ Complaint Received — Yesterday, 6:18 PM",
 "✅ AI Categorized — Yesterday, 6:18 PM",
 "✅ Assigned to Delivery Ops — Yesterday, 6:20 PM",
 "✅ Investigation Completed — Yesterday, 7:45 PM",
 "✅ Resolved — Credit Applied — Yesterday, 7:52 PM",
 ],
 },
 "CMP-10144": {
 status: "Escalated to Manager",
 statusIcon: "🔴",
 category: "Damaged Item",
 created: "2 days ago, 2:11 PM",
 assignedTeam: "Quality Assurance — Koramangala",
 latestUpdate:
 "This complaint has been escalated to a senior manager due to repeated packaging quality issues at your assigned store. We are prioritizing your case.",
 estimatedResolution: "Within 4 hours (escalated priority)",
 timeline: [
 "✅ Complaint Received — 2 days ago, 2:11 PM",
 "✅ AI Categorized — 2 days ago, 2:11 PM",
 "✅ Assigned to QA Team — 2 days ago, 2:14 PM",
 "✅ Initial Investigation — 2 days ago, 3:30 PM",
 "🔴 Escalated to Manager — Today, 9:05 AM",
 "○ Resolution Pending",
 ],
 },
};

function startTrackFlow(
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 return {
 response: {
 text: "Sure! I can help you track your complaint.\n\nPlease enter your Complaint ID.\n\nExample: **CMP-10482**",
 },
 newState: {
 ...state,
 activeFlow: "track",
 trackStep: "ask_id",
 collectedData: {},
 },
 };
}

function processTrack(
 input: string,
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 if (state.trackStep === "ask_id") {
 const complaintId = input.trim().toUpperCase().replace(/\s+/g, "");
 const data = TRACKED_COMPLAINTS[complaintId];

 if (!data) {
 return {
 response: {
 text: "We couldn't find a complaint with that ID.\n\nPlease verify the Complaint ID or contact support.",
 chips: ["Contact Support", "Try Again", "Return Home"],
 isComplete: true,
 },
 newState: getInitialState(),
 };
 }

 return {
 response: {
 text: `Here's the current status for your complaint:`,
 sections: [
 {
 title: "Complaint Status",
 severity: data.statusIcon === "🟢" ? "healthy" : data.statusIcon === "🔴" ? "critical" : "warning",
 badge: data.statusIcon + " " + data.status,
 metrics: [
 { label: "Complaint ID", value: complaintId },
 { label: "Category", value: data.category },
 { label: "Created", value: data.created },
 { label: "Assigned Team", value: data.assignedTeam },
 ],
 },
 {
 title: "Latest Update",
 severity: "info",
 bullets: [data.latestUpdate, `Estimated Resolution: ${data.estimatedResolution}`],
 },
 {
 title: "Progress Timeline",
 severity: data.statusIcon === "🟢" ? "healthy" : "info",
 bullets: data.timeline,
 },
 ],
 chips: ["Contact Support", "Return Home"],
 isComplete: true,
 },
 newState: {
 ...getInitialState(),
 collectedData: { complaintId },
 },
 };
 }
 return { response: getWelcomeResponse(), newState: getInitialState() };
}

// ===== REFUND FLOW =====

function startRefundFlow(
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 return {
 response: {
 text: "I'll look up your refund status. Please provide your Refund ID or Order Number.",
 },
 newState: {
 ...state,
 activeFlow: "refund",
 refundStep: "ask_id",
 collectedData: {},
 },
 };
}

function processRefund(
 input: string,
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 if (state.refundStep === "ask_id") {
 const refundId = input.trim().toUpperCase();
 return {
 response: {
 text: `Here's the refund status for **${refundId}**:`,
 sections: [
 {
 title: "Refund Details",
 severity: "healthy",
 badge: "Processing",
 metrics: [
 { label: "Refund ID", value: `REF-${refundId.replace(/[^0-9]/g, "").slice(0, 5) || "47291"}` },
 { label: "Amount", value: "₹847.00" },
 { label: "Method", value: "Original Payment" },
 { label: "Initiated", value: "Dec 14, 2024" },
 ],
 },
 {
 title: "Refund Progress",
 severity: "info",
 bullets: [
 "✅ Refund Approved — Dec 14, 3:22 PM",
 "✅ Processing Initiated — Dec 14, 3:25 PM",
 "⏳ Bank Processing — In Progress (1-3 business days)",
 "⬚ Credited to Account — Expected by Dec 17",
 ],
 },
 {
 title: "Important Notes",
 severity: "warning",
 bullets: [
 "Refund timelines depend on your bank's processing speed",
 "UPI refunds are typically faster (4-6 hours)",
 "Credit card refunds may take 5-7 business days",
 "Contact your bank if not received by the expected date",
 ],
 },
 ],
 isComplete: true,
 },
 newState: {
 ...getInitialState(),
 collectedData: { refundId },
 },
 };
 }
 return { response: getWelcomeResponse(), newState: getInitialState() };
}

// ===== CONTACT SUPPORT FLOW =====

function startContactFlow(
 state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 return {
 response: {
 text: "Here are the ways you can reach our support team:",
 sections: [
 {
 title: "Support Channels",
 severity: "info",
 badge: "Available 24/7",
 bullets: [
 "💬 Live Chat — Instant connection with a support agent (avg wait: 45 seconds)",
 "📧 Email — support@darkops.com (response within 2 hours)",
 "📞 Phone — 1800-DARKOPS (1800-327-5677) — 24/7 toll-free",
 "📖 Help Center — help.darkops.com — FAQs, guides, and tutorials",
 ],
 },
 {
 title: "Quick Tips",
 severity: "healthy",
 bullets: [
 "For order issues, have your Order ID ready",
 "For fastest resolution, use Live Chat during business hours",
 "Email is best for non-urgent queries with attachments",
 "Phone support prioritizes Premium customers",
 ],
 },
 ],
 isComplete: true,
 },
 newState: getInitialState(),
 };
}

function processContact(
 _input: string,
 _state: ConversationState
): { response: EngineResponse; newState: ConversationState } {
 return startContactFlow(_state);
}
