","/* DarkOps Customer Assistant — Premium Dark Theme (Teal Accent) */

/* ===== Reset & Base ===== */
*,
*::before,
*::after {
 box-sizing: border-box;
 margin: 0;
 padding: 0;
}

.assist-page {
 display: flex;
 flex-direction: column;
 height: 100vh;
 width: 100vw;
 background: #0a0e14;
 color: #e2e8f0;
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
 overflow: hidden;
}

/* ===== Header ===== */
.assist-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 16px 24px;
 background: linear-gradient(180deg, #111621 0%, #0d1117 100%);
 border-bottom: 1px solid #1a2035;
 flex-shrink: 0;
}

.assist-brand {
 display: flex;
 align-items: center;
 gap: 12px;
}

.assist-logo {
 width: 36px;
 height: 36px;
 border-radius: 10px;
 background: linear-gradient(135deg, #06b6d4 0%, #0891b2 50%, #0e7490 100%);
 display: flex;
 align-items: center;
 justify-content: center;
 box-shadow: 0 0 20px rgba(6, 182, 212, 0.3);
}

.assist-logo svg {
 width: 20px;
 height: 20px;
 fill: white;
}

.assist-title {
 font-size: 18px;
 font-weight: 700;
 color: #f1f5f9;
 letter-spacing: -0.3px;
}

.assist-subtitle {
 font-size: 12px;
 color: #06b6d4;
 font-weight: 500;
 letter-spacing: 0.5px;
 text-transform: uppercase;
}

.assist-status {
 display: flex;
 align-items: center;
 gap: 8px;
 font-size: 12px;
 color: #22c55e;
 font-weight: 500;
}

.assist-status-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: #22c55e;
 animation: assist-pulse-dot 2s ease-in-out infinite;
}

@keyframes assist-pulse-dot {
 0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.4); }
 50% { opacity: 0.8; box-shadow: 0 0 0 6px rgba(34, 197, 94, 0); }
}

/* ===== New Conversation Button ===== */
.assist-new-btn {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 6px 12px;
 background: rgba(6, 182, 212, 0.1);
 border: 1px solid rgba(6, 182, 212, 0.3);
 border-radius: 8px;
 font-size: 12px;
 color: #06b6d4;
 cursor: pointer;
 transition: all 0.2s ease;
 font-weight: 500;
}

.assist-new-btn:hover {
 background: rgba(6, 182, 212, 0.2);
 border-color: #06b6d4;
 transform: translateY(-1px);
}

/* ===== Conversation Area ===== */
.assist-conversation {
 flex: 1;
 overflow-y: auto;
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 20px;
 scroll-behavior: smooth;
}

.assist-conversation::-webkit-scrollbar {
 width: 6px;
}

.assist-conversation::-webkit-scrollbar-track {
 background: transparent;
}

.assist-conversation::-webkit-scrollbar-thumb {
 background: #1e293b;
 border-radius: 3px;
}

.assist-conversation::-webkit-scrollbar-thumb:hover {
 background: #334155;
}

/* ===== Welcome Message ===== */
.assist-welcome {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: 40px 24px;
 text-align: center;
}

.assist-welcome-icon {
 width: 64px;
 height: 64px;
 border-radius: 16px;
 background: linear-gradient(135deg, #06b6d4 0%, #0891b2 50%, #0e7490 100%);
 display: flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 20px;
 box-shadow: 0 0 40px rgba(6, 182, 212, 0.25);
}

.assist-welcome-icon svg {
 width: 32px;
 height: 32px;
 fill: white;
}

.assist-welcome h2 {
 font-size: 22px;
 font-weight: 700;
 color: #f1f5f9;
 margin-bottom: 8px;
}

.assist-welcome p {
 font-size: 14px;
 color: #64748b;
 max-width: 420px;
 line-height: 1.6;
 margin-bottom: 24px;
}

/* ===== Action Cards (Welcome Options) ===== */
.assist-action-cards {
 display: grid;
 grid-template-columns: repeat(2, 1fr);
 gap: 12px;
 max-width: 520px;
 width: 100%;
}

.assist-action-card {
 display: flex;
 align-items: flex-start;
 gap: 12px;
 padding: 16px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 cursor: pointer;
 transition: all 0.25s ease;
 text-align: left;
}

.assist-action-card:hover {
 border-color: #06b6d4;
 background: #151d2e;
 transform: translateY(-2px);
 box-shadow: 0 8px 24px rgba(6, 182, 212, 0.1);
}

.assist-action-card-icon {
 font-size: 24px;
 flex-shrink: 0;
 width: 40px;
 height: 40px;
 display: flex;
 align-items: center;
 justify-content: center;
 background: rgba(6, 182, 212, 0.1);
 border-radius: 10px;
}

.assist-action-card-content {
 display: flex;
 flex-direction: column;
 gap: 4px;
}

.assist-action-card-title {
 font-size: 14px;
 font-weight: 600;
 color: #f1f5f9;
}

.assist-action-card-desc {
 font-size: 12px;
 color: #64748b;
 line-height: 1.4;
}

/* ===== Messages ===== */
.assist-message {
 display: flex;
 gap: 12px;
 animation: assist-fadeInUp 0.3s ease;
}

@keyframes assist-fadeInUp {
 from { opacity: 0; transform: translateY(10px); }
 to { opacity: 1; transform: translateY(0); }
}

.assist-message--user {
 flex-direction: row-reverse;
}

.assist-message-avatar {
 width: 32px;
 height: 32px;
 border-radius: 8px;
 flex-shrink: 0;
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 12px;
 font-weight: 700;
}

.assist-message--ai .assist-message-avatar {
 background: linear-gradient(135deg, #06b6d4, #0891b2);
 color: white;
}

.assist-message--ai .assist-message-avatar svg {
 width: 16px;
 height: 16px;
 fill: white;
}

.assist-message--user .assist-message-avatar {
 background: #1e293b;
 color: #94a3b8;
}

.assist-message-content {
 max-width: 85%;
 min-width: 0;
}

.assist-message--user .assist-message-content {
 display: flex;
 justify-content: flex-end;
}

.assist-user-bubble {
 background: #1e293b;
 border: 1px solid #334155;
 border-radius: 16px 16px 4px 16px;
 padding: 12px 16px;
 font-size: 14px;
 color: #e2e8f0;
 line-height: 1.5;
}

/* ===== AI Response ===== */
.assist-response {
 display: flex;
 flex-direction: column;
 gap: 12px;
 width: 100%;
}

.assist-response-text {
 font-size: 14px;
 color: #cbd5e1;
 line-height: 1.6;
 padding: 4px 0;
}

.assist-response-text strong {
 color: #f1f5f9;
 font-weight: 600;
}

/* ===== Section Cards ===== */
.assist-section {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 16px;
 transition: border-color 0.2s ease;
}

.assist-section:hover {
 border-color: #2a3555;
}

.assist-section--critical {
 border-left: 3px solid #ef4444;
}

.assist-section--warning {
 border-left: 3px solid #f59e0b;
}

.assist-section--healthy {
 border-left: 3px solid #22c55e;
}

.assist-section--info {
 border-left: 3px solid #3b82f6;
}

.assist-section-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 12px;
}

.assist-section-title {
 font-size: 13px;
 font-weight: 600;
 color: #f1f5f9;
 letter-spacing: -0.2px;
}

.assist-badge {
 font-size: 11px;
 font-weight: 600;
 padding: 3px 8px;
 border-radius: 4px;
 text-transform: uppercase;
 letter-spacing: 0.3px;
}

.assist-badge--critical {
 background: rgba(239, 68, 68, 0.15);
 color: #fca5a5;
 border: 1px solid rgba(239, 68, 68, 0.3);
}

.assist-badge--warning {
 background: rgba(245, 158, 11, 0.15);
 color: #fcd34d;
 border: 1px solid rgba(245, 158, 11, 0.3);
}

.assist-badge--healthy {
 background: rgba(34, 197, 94, 0.15);
 color: #86efac;
 border: 1px solid rgba(34, 197, 94, 0.3);
}

.assist-badge--info {
 background: rgba(59, 130, 246, 0.15);
 color: #93c5fd;
 border: 1px solid rgba(59, 130, 246, 0.3);
}

/* ===== Bullet Lists ===== */
.assist-bullets {
 list-style: none;
 display: flex;
 flex-direction: column;
 gap: 8px;
}

.assist-bullet {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 font-size: 13px;
 color: #94a3b8;
 line-height: 1.5;
}

.assist-bullet::before {
 content: "";
 width: 5px;
 height: 5px;
 border-radius: 50%;
 background: #475569;
 flex-shrink: 0;
 margin-top: 7px;
}

.assist-section--critical .assist-bullet::before {
 background: #ef4444;
}

.assist-section--warning .assist-bullet::before {
 background: #f59e0b;
}

.assist-section--healthy .assist-bullet::before {
 background: #22c55e;
}

.assist-section--info .assist-bullet::before {
 background: #3b82f6;
}

/* ===== Metrics Grid ===== */
.assist-metrics {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
 gap: 8px;
}

.assist-metric {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 8px 12px;
 background: #0d1117;
 border-radius: 8px;
 border: 1px solid #1a2035;
}

.assist-metric-label {
 font-size: 11px;
 color: #64748b;
 font-weight: 500;
}

.assist-metric-value {
 font-size: 13px;
 color: #e2e8f0;
 font-weight: 600;
}

/* ===== Chips ===== */
.assist-chips {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
 margin-top: 8px;
}

.assist-chip {
 display: inline-flex;
 align-items: center;
 padding: 8px 14px;
 background: #111621;
 border: 1px solid #1e293b;
 border-radius: 20px;
 font-size: 13px;
 color: #94a3b8;
 cursor: pointer;
 transition: all 0.2s ease;
 white-space: nowrap;
 user-select: none;
}

.assist-chip:hover {
 background: #1a2035;
 border-color: #06b6d4;
 color: #67e8f9;
 transform: translateY(-1px);
 box-shadow: 0 2px 8px rgba(6, 182, 212, 0.15);
}

/* ===== Typing Indicator ===== */
.assist-typing {
 display: flex;
 align-items: center;
 gap: 12px;
 animation: assist-fadeInUp 0.3s ease;
}

.assist-typing-dots {
 display: flex;
 align-items: center;
 gap: 4px;
 padding: 12px 16px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 16px;
}

.assist-typing-dot {
 width: 7px;
 height: 7px;
 border-radius: 50%;
 background: #06b6d4;
 animation: assist-typing-bounce 1.4s ease-in-out infinite;
}

.assist-typing-dot:nth-child(2) {
 animation-delay: 0.2s;
}

.assist-typing-dot:nth-child(3) {
 animation-delay: 0.4s;
}

@keyframes assist-typing-bounce {
 0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
 30% { transform: translateY(-6px); opacity: 1; }
}

.assist-typing-text {
 font-size: 12px;
 color: #64748b;
 font-style: italic;
}

/* ===== Input Bar ===== */
.assist-input-bar {
 padding: 16px 24px;
 background: #0d1117;
 border-top: 1px solid #1a2035;
 flex-shrink: 0;
}

.assist-input-container {
 display: flex;
 align-items: center;
 gap: 12px;
 background: #111621;
 border: 1px solid #1e293b;
 border-radius: 12px;
 padding: 4px 4px 4px 16px;
 transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.assist-input-container:focus-within {
 border-color: #06b6d4;
 box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.1);
}

.assist-input {
 flex: 1;
 background: transparent;
 border: none;
 outline: none;
 font-size: 14px;
 color: #e2e8f0;
 padding: 10px 0;
 font-family: inherit;
}

.assist-input::placeholder {
 color: #475569;
}

.assist-send-btn {
 width: 38px;
 height: 38px;
 border-radius: 8px;
 background: linear-gradient(135deg, #06b6d4, #0891b2);
 border: none;
 cursor: pointer;
 display: flex;
 align-items: center;
 justify-content: center;
 transition: all 0.2s ease;
 flex-shrink: 0;
}

.assist-send-btn:hover:not(:disabled) {
 transform: scale(1.05);
 box-shadow: 0 0 16px rgba(6, 182, 212, 0.4);
}

.assist-send-btn:disabled {
 opacity: 0.4;
 cursor: not-allowed;
}

.assist-send-btn svg {
 width: 18px;
 height: 18px;
 fill: white;
}

/* ===== Complete State (New Conversation prompt) ===== */
.assist-complete-bar {
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 12px;
 padding: 12px;
 margin-top: 8px;
}

.assist-complete-btn {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 10px 20px;
 background: linear-gradient(135deg, rgba(6, 182, 212, 0.15), rgba(8, 145, 178, 0.1));
 border: 1px solid rgba(6, 182, 212, 0.4);
 border-radius: 20px;
 font-size: 13px;
 color: #67e8f9;
 cursor: pointer;
 transition: all 0.25s ease;
 font-weight: 500;
}

.assist-complete-btn:hover {
 background: linear-gradient(135deg, rgba(6, 182, 212, 0.25), rgba(8, 145, 178, 0.2));
 border-color: #06b6d4;
 transform: translateY(-1px);
 box-shadow: 0 4px 16px rgba(6, 182, 212, 0.2);
}

/* ===== Inline Action Cards (in messages) ===== */
.assist-inline-cards {
 display: grid;
 grid-template-columns: repeat(2, 1fr);
 gap: 10px;
 margin-top: 12px;
}

.assist-inline-card {
 display: flex;
 align-items: flex-start;
 gap: 10px;
 padding: 14px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 cursor: pointer;
 transition: all 0.25s ease;
}

.assist-inline-card:hover {
 border-color: #06b6d4;
 background: #151d2e;
 transform: translateY(-2px);
 box-shadow: 0 6px 20px rgba(6, 182, 212, 0.08);
}

.assist-inline-card-icon {
 font-size: 20px;
 flex-shrink: 0;
 width: 36px;
 height: 36px;
 display: flex;
 align-items: center;
 justify-content: center;
 background: rgba(6, 182, 212, 0.1);
 border-radius: 8px;
}

.assist-inline-card-content {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.assist-inline-card-title {
 font-size: 13px;
 font-weight: 600;
 color: #f1f5f9;
}

.assist-inline-card-desc {
 font-size: 11px;
 color: #64748b;
 line-height: 1.4;
}

/* ===== Responsive ===== */
@media (max-width: 600px) {
 .assist-action-cards,
 .assist-inline-cards {
 grid-template-columns: 1fr;
 }

 .assist-header {
 padding: 12px 16px;
 }

 .assist-conversation {
 padding: 16px;
 }

 .assist-input-bar {
 padding: 12px 16px;
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useRef, useEffect } from "react";
import "./assistant.css";
import {
 ConversationState,
 EngineResponse,
 SectionItem,
 getInitialState,
 getWelcomeResponse,
 processInput,
} from "./conversationEngine";

interface Message {
 id: string;
 type: "user" | "ai";
 text?: string;
 response?: EngineResponse;
}

function AssistantIcon() {
 return (
 <svg viewBox="0 0 24 24">
 <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm0 14H6l-2 2V4h16v12z" />
 </svg>
 );
}

function SendIcon() {
 return (
 <svg viewBox="0 0 24 24">
 <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
 </svg>
 );
}

function renderMarkdownText(text: string): React.ReactNode {
 const parts = text.split(/(\*\*[^*]+\*\*)/g);
 return parts.map((part, i) => {
 if (part.startsWith("**") && part.endsWith("**")) {
 return <strong key={i}>{part.slice(2, -2)}</strong>;
 }
 return <span key={i}>{part}</span>;
 });
}

function SectionCard({ section }: { section: SectionItem; key?: React.Key }) {
 const sev = section.severity || "info";
 return (
 <div className={`assist-section assist-section--${sev}`}>
 <div className="assist-section-header">
 <span className="assist-section-title">{section.title}</span>
 {section.badge && (
 <span className={`assist-badge assist-badge--${sev}`}>{section.badge}</span>
 )}
 </div>
 {section.bullets && (
 <ul className="assist-bullets">
 {section.bullets.map((b, i) => (
 <li key={i} className="assist-bullet">
 {b}
 </li>
 ))}
 </ul>
 )}
 {section.metrics && (
 <div className="assist-metrics">
 {section.metrics.map((m, i) => (
 <div key={i} className="assist-metric">
 <span className="assist-metric-label">{m.label}</span>
 <span className="assist-metric-value">{m.value}</span>
 </div>
 ))}
 </div>
 )}
 </div>
 );
}

function AIResponseView({
 response,
 onChipClick,
 onActionCardClick,
 onNewConversation,
}: {
 response: EngineResponse;
 onChipClick: (chip: string) => void;
 onActionCardClick: (action: string) => void;
 onNewConversation: () => void;
}) {
 return (
 <div className="assist-response">
 <div className="assist-response-text">{renderMarkdownText(response.text)}</div>

 {response.sections && response.sections.map((sec, i) => (
 <SectionCard key={i} section={sec} />
 ))}

 {response.actionCards && (
 <div className="assist-inline-cards">
 {response.actionCards.map((card, i) => (
 <div
 key={i}
 className="assist-inline-card"
 onClick={() => onActionCardClick(card.action)}
 >
 <div className="assist-inline-card-icon">{card.icon}</div>
 <div className="assist-inline-card-content">
 <div className="assist-inline-card-title">{card.title}</div>
 <div className="assist-inline-card-desc">{card.description}</div>
 </div>
 </div>
 ))}
 </div>
 )}

 {response.chips && (
 <div className="assist-chips">
 {response.chips.map((chip, i) => (
 <button
 key={i}
 className="assist-chip"
 onClick={() => onChipClick(chip)}
 >
 {chip}
 </button>
 ))}
 </div>
 )}

 {response.isComplete && (
 <div className="assist-complete-bar">
 <button className="assist-complete-btn" onClick={onNewConversation}>
 ↻ Start New Conversation
 </button>
 </div>
 )}
 </div>
 );
}

function TypingIndicator() {
 return (
 <div className="assist-typing">
 <div className="assist-message-avatar" style={{ background: "linear-gradient(135deg, #06b6d4, #0891b2)" }}>
 <AssistantIcon />
 </div>
 <div className="assist-typing-dots">
 <div className="assist-typing-dot" />
 <div className="assist-typing-dot" />
 <div className="assist-typing-dot" />
 </div>
 <span className="assist-typing-text">Processing your request...</span>
 </div>
 );
}

export default function AssistantApp() {
 const [messages, setMessages] = useState<Message[]>([]);
 const [input, setInput] = useState("");
 const [isLoading, setIsLoading] = useState(false);
 const [convState, setConvState] = useState<ConversationState>(getInitialState());
 const conversationRef = useRef<HTMLDivElement>(null);
 const inputRef = useRef<HTMLInputElement>(null);

 useEffect(() => {
 if (conversationRef.current) {
 conversationRef.current.scrollTop = conversationRef.current.scrollHeight;
 }
 }, [messages, isLoading]);

 const handleSend = async (text: string) => {
 if (!text.trim() || isLoading) return;

 const userMsg: Message = {
 id: Date.now().toString(),
 type: "user",
 text: text.trim(),
 };

 setMessages((prev) => [...prev, userMsg]);
 setInput("");
 setIsLoading(true);

 // Simulate brief processing delay
 await new Promise((resolve) => setTimeout(resolve, 600 + Math.random() * 400));

 const { response, newState } = processInput(text.trim(), convState);
 setConvState(newState);

 const aiMsg: Message = {
 id: (Date.now() + 1).toString(),
 type: "ai",
 response,
 };

 setMessages((prev) => [...prev, aiMsg]);
 setIsLoading(false);
 inputRef.current?.focus();
 };

 const handleActionCard = async (action: string) => {
 if (isLoading) return;

 // Simulate the user selecting an action
 const actionLabels: Record<string, string> = {
 complaint: "Raise Complaint",
 track: "Track Complaint",
 refund: "Refund Status",
 contact: "Contact Support",
 };

 const userMsg: Message = {
 id: Date.now().toString(),
 type: "user",
 text: actionLabels[action] || action,
 };

 setMessages((prev) => [...prev, userMsg]);
 setIsLoading(true);

 await new Promise((resolve) => setTimeout(resolve, 500 + Math.random() * 300));

 const { response, newState } = processInput(actionLabels[action] || action, convState);
 setConvState(newState);

 const aiMsg: Message = {
 id: (Date.now() + 1).toString(),
 type: "ai",
 response,
 };

 setMessages((prev) => [...prev, aiMsg]);
 setIsLoading(false);
 inputRef.current?.focus();
 };

 const handleChipClick = (chip: string) => {
 handleSend(chip);
 };

 const handleNewConversation = () => {
 setMessages([]);
 setConvState(getInitialState());
 setInput("");
 inputRef.current?.focus();
 };

 const handleSubmit = (e: React.FormEvent) => {
 e.preventDefault();
 handleSend(input);
 };

 const handleKeyDown = (e: React.KeyboardEvent) => {
 if (e.key === "Enter" && !e.shiftKey) {
 e.preventDefault();
 handleSend(input);
 }
 };

 const welcome = getWelcomeResponse();

 return (
 <div className="assist-page">
 {/* Header */}
 <header className="assist-header">
 <div className="assist-brand">
 <div className="assist-logo">
 <AssistantIcon />
 </div>
 <div>
 <div className="assist-title">DarkOps AI</div>
 <div className="assist-subtitle">Customer Assistant</div>
 </div>
 </div>
 <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
 {messages.length > 0 && (
 <button className="assist-new-btn" onClick={handleNewConversation}>
 ↻ New Chat
 </button>
 )}
 <div className="assist-status">
 <div className="assist-status-dot" />
 Ready to help
 </div>
 </div>
 </header>

 {/* Conversation */}
 <div className="assist-conversation" ref={conversationRef}>
 {messages.length === 0 && !isLoading && (
 <div className="assist-welcome">
 <div className="assist-welcome-icon">
 <AssistantIcon />
 </div>
 <h2>DarkOps Customer Assistant</h2>
 <p>
 I can help you raise complaints, track existing issues, check refund
 status, or connect you with our support team. What would you like to do?
 </p>
 <div className="assist-action-cards">
 {welcome.actionCards!.map((card, i) => (
 <div
 key={i}
 className="assist-action-card"
 onClick={() => handleActionCard(card.action)}
 >
 <div className="assist-action-card-icon">{card.icon}</div>
 <div className="assist-action-card-content">
 <div className="assist-action-card-title">{card.title}</div>
 <div className="assist-action-card-desc">{card.description}</div>
 </div>
 </div>
 ))}
 </div>
 </div>
 )}

 {messages.map((msg) => {
 if (msg.type === "user") {
 return (
 <div key={msg.id} className="assist-message assist-message--user">
 <div className="assist-message-avatar">You</div>
 <div className="assist-message-content">
 <div className="assist-user-bubble">{msg.text}</div>
 </div>
 </div>
 );
 }
 return (
 <div key={msg.id} className="assist-message assist-message--ai">
 <div className="assist-message-avatar">
 <AssistantIcon />
 </div>
 <div className="assist-message-content">
 {msg.response && (
 <AIResponseView
 response={msg.response}
 onChipClick={handleChipClick}
 onActionCardClick={handleActionCard}
 onNewConversation={handleNewConversation}
 />
 )}
 </div>
 </div>
 );
 })}

 {isLoading && <TypingIndicator />}
 </div>

 {/* Input Bar */}
 <form className="assist-input-bar" onSubmit={handleSubmit}>
 <div className="assist-input-container">
 <input
 ref={inputRef}
 className="assist-input"
 type="text"
 placeholder="Type your message or select an option above..."
 value={input}
 onChange={(e) => setInput(e.target.value)}
 onKeyDown={handleKeyDown}
 disabled={isLoading}
 autoFocus
 />
 <button
 type="submit"
 className="assist-send-btn"
 disabled={!input.trim() || isLoading}
 >
 <SendIcon />
 </button>
 </div>
 </form>
 </div>
 );
}
